import requests

def moderate_messages(messages):
    url = "https://api.perspectiveapi.com/v1/comment/analyze"
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {os.getenv('PERSPECTIVE_API_KEY')}"
    }
    payload = {
        "comment": {"text": messages},
        "languages": ["en"],
        "requestedAttributes": {
            "TOXICITY": {},
            "SEVERE_TOXICITY": {},
            "IDENTITY_ATTACK": {},
            "INSULT": {},
            "PROFANITY": {}
        }
    }
    response = requests.post(url, headers=headers, json=payload)
    response.raise_for_status()
    results = response.json()["attributeScores"]
    decisions = []
    for msg_results in results:
        toxic_score = msg_results["TOXICITY"]["summaryScore"]["value"]
        severe_toxic_score = msg_results["SEVERE_TOXICITY"]["summaryScore"]["value"]
        is_toxic = toxic_score > 0.5 or severe_toxic_score > 0.5
        decisions.append(is_toxic)
    return decisions
